// Real custom iterator and actual unchanged UnordItems methods.
#![feature(panic_can_unwind,panic_internals)]
#![allow(internal_features)]
use rustc_data_structures::unord::UnordItems;
use std::{cell::Cell,io::{self,Write},panic::{self,AssertUnwindSafe,catch_unwind}};
#[derive(Clone,Copy)]struct Config{length:usize,pattern:usize,next_fail:isize,item_fail:i64,iterator_fail:bool,resume:bool,clonefrom:bool,clone_fail:bool}
thread_local!{static CONFIG:Cell<Config>=const{Cell::new(Config{length:0,pattern:0,next_fail:-1,item_fail:-1,iterator_fail:false,resume:false,clonefrom:false,clone_fail:false})};}
fn event(s:impl AsRef<str>){println!("{}",s.as_ref());io::stdout().flush().unwrap();}fn hex(s:&str)->String{s.bytes().map(|b|format!("{b:02x}")).collect()}
#[track_caller]fn raise(s:&'static str)->!{if CONFIG.get().resume{panic::resume_unwind(Box::new(s))}else{panic::panic_any(s)}}
struct Value(u64);impl Clone for Value{fn clone(&self)->Self{event("item_clone");Self(self.0)}}impl Drop for Value{fn drop(&mut self){event(format!("item:{}:{}",self.0,std::thread::panicking()));if self.0 as i64==CONFIG.get().item_fail{raise("item_drop")}}}
struct Input{next:usize}
impl Clone for Input{fn clone(&self)->Self{event(format!("clone:{}:{}",self.next,std::thread::panicking()));if CONFIG.get().clone_fail{raise("clone")};Self{next:self.next}}}
impl Drop for Input{fn drop(&mut self){event(format!("iterator:{}:{}",self.next,std::thread::panicking()));if CONFIG.get().iterator_fail&&(!CONFIG.get().clonefrom||self.next==99){raise("iterator_drop")}}}
impl Iterator for Input{type Item=Value;fn next(&mut self)->Option<Value>{let n=self.next;self.next+=1;event(format!("next:{n}:{}",std::thread::panicking()));if n as isize==CONFIG.get().next_fail{raise("next")};if CONFIG.get().pattern==1{if n==1{Some(Value(7))}else{None}}else if n<CONFIG.get().length{Some(Value(n as u64))}else{None}}fn size_hint(&self)->(usize,Option<usize>){event("hint");(0,None)}fn count(self)->usize{event(format!("count:{}",self.next));1000+CONFIG.get().length}}
fn message(p:Box<dyn std::any::Any+Send>)->String{p.downcast_ref::<&str>().map(|s|(*s).to_owned()).unwrap_or_else(||"opaque".into())}
fn body(action:usize){event(format!("body:{}",std::thread::panicking()));let result=catch_unwind(AssertUnwindSafe(||{let items=UnordItems::new(Input{next:0});match action{0=>{let result=items.get_only();event(format!("returned:{}",result.as_ref().map(|v|v.0.to_string()).unwrap_or_else(||"none".into())));drop(result)},1=>event(format!("returned:{}",items.count())),2=>{let cloned=items.clone();event(format!("returned:{}",cloned.count()));drop(items)},3=>{drop(items);let empty=UnordItems::<Value,std::iter::Empty<Value>>::empty();let cloned=empty.clone();event(format!("empty:{}:{}",empty.count(),cloned.count()))},4=>{let mut destination=UnordItems::new(Input{next:99});destination.clone_from(&items);event(format!("returned:{}",destination.count()));drop(items)},_=>unreachable!()}}));event(format!("caught:{}:{}",hex(&result.err().map(message).unwrap_or_default()),std::thread::panicking()));}
struct Outer(usize);impl Drop for Outer{fn drop(&mut self){body(self.0)}}
fn main(){let args:Vec<_>=std::env::args().collect();let mode=args[1].clone();let action=args[2].parse::<usize>().unwrap();let n:Vec<i64>=args[3].split(',').map(|v|v.parse().unwrap()).collect();CONFIG.set(Config{length:n[0]as usize,pattern:n[1]as usize,next_fail:n[2]as isize,item_fail:n[3],iterator_fail:n[4]!=0,resume:n[5]!=0,clonefrom:action==4,clone_fail:action==4&&n[2]==0});let processing=mode=="processing";panic::set_hook(Box::new(move|info|{let payload=info.payload().downcast_ref::<&str>().copied().unwrap_or("");let kind=if info.payload().is::<&str>(){"static_str"}else{"opaque"};let(file,line,column)=info.location().map(|l|(l.file(),l.line(),l.column())).unwrap_or(("",0,0));event(format!("HOOK:{kind}:{}:{}:{}:{}:{}:{line}:{column}",hex(payload),std::thread::panicking(),info.can_unwind(),info.force_no_backtrace(),hex(file)));if processing{body(action)}}));match mode.as_str(){"normal"=>body(action),"unwind"=>{let _=catch_unwind(||{let _outer=Outer(action);panic::panic_any("outer")});event("outer_end:false")},"processing"=>{let _=catch_unwind(||panic::panic_any("outer"));event("outer_end:false")},_=>panic!("mode")}}
